def isValidEmail(s):
    if s.count('@') != 1:
        return False
    local, domain = s.split('@')
    if not 1 <= len(local) <= 64:
        return False
    if local[0] == '.' or local[-1] == '.' or '..' in local:
        return False
    for c in local:
        if not ('a' <= c <= 'z' or '0' <= c <= '9' or c in '._-'):
            return False
    labels = domain.split('.')
    if len(labels) < 2:
        return False
    for lab in labels:
        if not 1 <= len(lab) <= 63:
            return False
        if lab[0] == '-' or lab[-1] == '-':
            return False
        for c in lab:
            if not ('a' <= c <= 'z' or '0' <= c <= '9' or c == '-'):
                return False
    tld = labels[-1]
    if len(tld) < 2:
        return False
    for c in tld:
        if not 'a' <= c <= 'z':
            return False
    return True
